@@ -195,6 +195,18 @@ namespace eka2l1::arm::aot {
                 guest_memory_op(*this, write ? op_i32_store : op_i32_load, 2);
                 return;
             }
+            if (memory_experiment::enabled() && (!write || common::code_tracking::skip_code_write_guards())) {
+                direct_access(*this, size, write, [&] {
+                    if (defer_memory && restartable_access) {
+                        get_local(COUNT); i32_const(1); op(op_i32_sub); set_local(COUNT);
+                        bail(current_pc, 0, exit_census::memory);
+                    } else {
+                        state_ptr(); get_local(ADDRESS); if(write) get_local(VALUE);
+                        slow_call(func_idx);
+                    }
+                });
+                return;
+            }
             // Each access checks the current TLB mapping and permissions.
             op(op_block); op(write ? type_void : type_i32);
             if(memory_experiment::mode) direct_host(*this, ADDRESS, size, write, 1);
diff --git a/src/emu/cpu/src/aot/thumb_translator.cpp b/src/emu/cpu/src/aot/thumb_translator.cpp
index f06e7ef82..b53dabd1b 100644
--- a/src/emu/cpu/src/aot/thumb_translator.cpp
+++ b/src/emu/cpu/src/aot/thumb_translator.cpp
@@ -242,6 +242,13 @@ namespace eka2l1::arm::aot {
             const unsigned size = func_idx < 2 ? 4 : func_idx < 4 ? 1 : 2;
             if (write) set_local(VALUE);
             set_local(ADDRESS); set_local(HOST); // consume imported state argument
+            if(memory_experiment::enabled()) {
+                direct_access(*this,size,write,[&] {
+                    state_ptr(); get_local(ADDRESS); if(write) get_local(VALUE);
+                    slow_call(func_idx);
+                });
+                return;
+            }
             if (span_active && !memory_experiment::enabled()) {
                 get_local(SPAN_HOST); op(op_if); op(write?type_void:type_i32);
                 get_local(SPAN_HOST); get_local(ADDRESS); i32_const(4095); op(op_i32_and); op(op_i32_add);

